// O comportamento é escolhido em tempo de execução pela flag.

function processarPagamento(pedido) {
  if (featureFlag.ativa('novo-fluxo-pagamento', pedido.clienteId)) {
    return novoFluxoPagamento(pedido);
  }
  return fluxoPagamentoAtual(pedido);
}

